            distance = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
            edges.append((distance, i, j))

    # Sort edges by distance
    edges.sort()

    def can_be_happy(D):
        parent = list(range(N))
        rank = [0] * N
