    # Binary search on D to find the minimal D
    left, right = 0.0, 1e7
    epsilon = 1e-6

    while right - left > epsilon:
        mid = (left + right) / 2.0
        if can_be_happy(mid):
            right = mid
        else:
            left = mid

    return left

