def find_minimal_D(N, K, cities):
    def can_build_with_distance(D):
        graph = {i: [] for i in range(N)}
        # Build graph with cities connected by roads shorter than D
        for i in range(N):
            for j in range(i + 1, N):
                x1, y1, _ = cities[i]
                x2, y2, _ = cities[j]
                distance = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
                if distance <= D:
                    graph[i].append(j)
                    graph[j].append(i)

        visited = [False] * N

        def dfs(node, subset):
            stack = [node]
            while stack:
                current = stack.pop()
                if visited[current]:
                    continue
                visited[current] = True
                subset.append(cities[current][2])
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

        # Check each connected component
        for start in range(N):
            if not visited[start]:
                subset = []
                dfs(start, subset)
                # Check if there is a subset whose sum is divisible by K
                sum_mod_k = [0] * K
                current_sum = 0
                for resident in subset:
                    current_sum += resident
                    sum_mod_k[current_sum % K] += 1
                if sum_mod_k[0] > 0:
                    return True
        return False

    # Binary search for the minimal D
    low, high = 0, 1e7
    precision = 1e-6

    while high - low > precision:
        mid = (low + high) / 2.0
        if can_build_with_distance(mid):
            high = mid
        else:
            low = mid

    return round(high, 3)

